func setupTestStepKindLabel(kind string) string {
	switch kind {
	case "command":
		return "Command"
	case "message":
		return "Message"
	case "tool":
		return "Tool use"
	}
	return "Agent step"
}

func reviewRunStateLabel(state string) string {
	switch state {
	case "finished":
		return "Finished"
	case "running":
		return "Running"
	case "failed":
		return "Failed"
	}
	return "Stopped"
}

